            push @bits, "$label=$value" if $value > 0;
        }
        push @worktree_lines, 'Worktree summary: ' . join(', ', @bits) if @bits;
        if (ref($worktree->{preview}) eq 'ARRAY' && @{$worktree->{preview}}) {
