    push @issues, _collect_stop_rule_issues($manifest, \@profiles, \@changed_files, $evidence, \%values, $current, scalar @mirror_refs);
    if (!@issues) {
        emit_system_message($pattern_message) if defined $pattern_message && length $pattern_message;
        return;
    }

