        File::Spec->catdir($Bin, "..", "modules"),
        File::Spec->catdir($Bin, "lib"),
    );
    for my $candidate (@candidates) {
        my $resolved = abs_path($candidate);
        next if !defined $resolved || !-d $resolved;
        unshift @INC, $resolved;
        last;
    }
}

