    my ($prompt) = @_;
    return 0 if !defined $prompt || !length $prompt;
    return $prompt =~ /\b(build|install|runtime|verify|verification|validate|validation|test|tests|docker|podman|container|shellcheck|wrangler|node|npx|uv|make|bash|command|dependency|dependencies)\b/i;
