    41	    my $flags = fcntl($handle, F_GETFL, 0);
    42	    return if !defined $flags;
    43	    fcntl($handle, F_SETFL, $flags | O_NONBLOCK);
    44	}
    45	
    46	sub _drain_handles {
    47	    my (%args) = @_;
    48	    my $selector = $args{selector};
    49	    my $stdout_ref = $args{stdout_ref};
    50	    my $stderr_ref = $args{stderr_ref};
    51	    my $deadline = $args{deadline};
    52	    my %targets = %{ $args{targets} };
    53	
    54	    while ($selector->count()) {
    55	        my $remaining = $deadline - time();
    56	        return 0 if $remaining <= 0;
    57	        my @ready = $selector->can_read($remaining > 1 ? 1 : $remaining);
    58	        next if !@ready;
    59	        for my $handle (@ready) {
    60	            my $buffer = '';
    61	            my $read = sysread($handle, $buffer, 8192);
    62	            if (!defined $read) {
    63	                next if $!{EAGAIN} || $!{EWOULDBLOCK};
    64	                $selector->remove($handle);
    65	                close $handle;
    66	                next;
    67	            }
    68	            if ($read == 0) {
    69	                $selector->remove($handle);
    70	                close $handle;
    71	                next;
    72	            }
    73	            if ($targets{$handle} eq 'stdout') {
    74	                ${$stdout_ref} .= $buffer;
    75	            } else {
    76	                ${$stderr_ref} .= $buffer;
    77	            }
    78	        }
    79	    }
    80	    return 1;
    81	}
    82	
    83	sub run_command {
    84	    my (%args) = @_;
    85	    my $command = _validate_command($args{command});
    86	    my $cwd = $args{cwd};
    87	    my $timeout = _validate_timeout($args{timeout});
    88	
    89	    my $previous_cwd = getcwd();
    90	    my $changed_cwd = 0;
    91	    if (defined $cwd && length $cwd) {
    92	        chdir $cwd or return { rc => 1, stdout => '', stderr => "unable to chdir to $cwd: $!" };
    93	        $changed_cwd = 1;
    94	    }
    95	
    96	    my ($stdout, $stderr) = ('', '');
    97	    my $stdout_handle;
    98	    my $stderr_handle = gensym();
    99	    my $pid;
   100	    my $spawn_ok = eval {
   101	        $pid = open3(undef, $stdout_handle, $stderr_handle, @{$command});
   102	        1;
   103	    };
   104	    my $spawn_error = $@;
   105	    if ($changed_cwd) {
   106	        chdir $previous_cwd or die "failed to restore working directory to $previous_cwd: $!";
   107	    }
   108	    return { rc => 1, stdout => '', stderr => $spawn_error || 'command failed to start' } if !$spawn_ok;
   109	
   110	    _set_nonblocking($stdout_handle) if defined $stdout_handle;
   111	    _set_nonblocking($stderr_handle);
   112	
   113	    my $selector = IO::Select->new();
   114	    my %targets;
   115	    if (defined $stdout_handle) {
   116	        $selector->add($stdout_handle);
   117	        $targets{$stdout_handle} = 'stdout';
   118	    }
   119	    if (defined $stderr_handle) {
   120	        $selector->add($stderr_handle);
   121	        $targets{$stderr_handle} = 'stderr';
   122	    }
   123	
   124	    my $deadline = time() + $timeout;
   125	    my $timed_out = 0;
   126	    my $pid_exited = 0;
   127	    my $wait_status = 0;
   128	    while (1) {
   129	        if (!$pid_exited) {
   130	            my $wait = waitpid($pid, WNOHANG);
   131	            if ($wait == $pid) {
   132	                $pid_exited = 1;
   133	                $wait_status = $?;
   134	            }
   135	        }
   136	        last if $pid_exited && !$selector->count();
   137	        if (!_drain_handles(
   138	                selector   => $selector,
   139	                stdout_ref => \$stdout,
   140	                stderr_ref => \$stderr,
   141	                deadline   => $deadline,
   142	                targets    => \%targets,
   143	            )) {
   144	            $timed_out = 1;
   145	            last;
   146	        }
   147	        if (!$pid_exited) {
   148	            my $wait = waitpid($pid, WNOHANG);
   149	            if ($wait == $pid) {
   150	                $pid_exited = 1;
   151	                $wait_status = $?;
   152	            }
   153	        }
   154	        last if $pid_exited && !$selector->count();
   155	    }
   156	
   157	    if ($timed_out) {
   158	        kill 'TERM', $pid;
   159	        my $grace_deadline = time() + 2;
   160	        _drain_handles(
   161	            selector   => $selector,
   162	            stdout_ref => \$stdout,
   163	            stderr_ref => \$stderr,
   164	            deadline   => $grace_deadline,
   165	            targets    => \%targets,
   166	        );
   167	        if (waitpid($pid, WNOHANG) == 0) {
   168	            kill 'KILL', $pid;
   169	            waitpid($pid, 0);
   170	        }
   171	        return { rc => 124, stdout => $stdout, stderr => 'command timed out' };
   172	    }
   173	
   174	    if (!$pid_exited) {
   175	        my $waited = waitpid($pid, 0);
   176	        if ($waited == $pid) {
   177	            $pid_exited = 1;
   178	            $wait_status = $?;
   179	        }
   180	    }
   181	    my $rc = $pid_exited ? ($wait_status >> 8) : 1;
   182	    return {
   183	        rc     => $rc,
   184	        stdout => $stdout // '',
   185	        stderr => $stderr // '',
   186	    };
   187	}
   188	
   189	sub read_file_tail {
   190	    my (%args) = @_;
   191	    my $path = $args{path};
   192	    return '' if !defined $path || !length $path;
   193	    return '' if !-f $path;
   194	    my $max_bytes = exists($args{max_bytes}) ? $args{max_bytes} : $DEFAULT_TAIL_BYTES;
   195	    return '' if ref($max_bytes) || $max_bytes !~ /\A[0-9]+\z/ || $max_bytes < 1 || $max_bytes > $MAX_TAIL_BYTES;
   196	
   197	    open my $fh, '<:raw', $path or return '';
   198	    my $size = -s $fh;
   199	    if (defined $size && $size > $max_bytes) {
   200	        seek $fh, $size - $max_bytes, 0 or return '';
   201	    }
   202	    local $/;
   203	    my $data = <$fh>;
   204	    close $fh;
   205	    return '' if !defined $data;
   206	    return $data;
   207	}
