    11	our @EXPORT_OK = qw(stop_system_message);
    12	
    13	sub _trim {
    14	    my ($value) = @_;
    15	    return '' if !defined $value || ref($value);
    16	    $value =~ s/^\s+|\s+$//g;
    17	    return $value;
    18	}
    19	
    20	sub _handoff_signal_lines {
    21	    my ($message) = @_;
    22	    my $text = stringify_payload_text(
    23	        value => $message,
    24	        limit => 16_384,
    25	    );
    26	    if (!length _trim($text)) {
    27	        return (
    28	            '- Last assistant message is empty; require an explicit subagent handoff before treating the work as complete.',
    29	        );
    30	    }
    31	
    32	    my @lines;
    33	    if ($text =~ /\b(?:could not run|couldn't run|unable to run|did not run|didn't run|skipped|cannot run|can't run|not run|permission denied|blocked)\b/i) {
    34	        push @lines, '- Last assistant message reports skipped or blocked validation; parent-side validation or a concrete risk note is still required.';
    35	    }
    36	    if ($text =~ /\b(?:test|tests|verify|verification|validate|validation|check|checks)\b/i) {
    37	        push @lines, '- Last assistant message mentions validation; parent should verify the exact commands and outcomes before closing the task.';
    38	    }
    39	    if ($text =~ /\b(?:touched|changed|modified|files?|paths?)\b/i) {
    40	        push @lines, '- Last assistant message appears to mention file ownership; parent should reconcile it against current git status.';
    41	    }
    42	    if ($text !~ /\b(?:owned files|checks run|validation|risk|risks|follow-up|followup|blocker|blocked)\b/i) {
    43	        push @lines, '- Last assistant message is missing a structured handoff; parent should require owned files, checks run, and residual risks before closing the task.';
    44	    }
    45	    if ($text =~ /\b(?:done|complete|completed|finished)\b/i
    46	            && $text !~ /\b(?:test|tests|verify|validation|check|risk|blocker)\b/i) {
    47	        push @lines, '- Last assistant message claims completion without clear validation or risk detail; parent should verify the close-out evidence explicitly.';
    48	    }
    49	    push @lines, '- Last assistant message includes a structured handoff; parent should reconcile it against the current worktree and validation evidence.'
    50	      if !@lines;
    51	    return @lines;
    52	}
    53	
    54	sub stop_system_message {
    55	    my (%args) = @_;
    56	    my $payload = ref($args{payload}) eq 'HASH' ? $args{payload} : {};
    57	    my $role_context = _trim($args{role_context});
    58	    my $agent_type = _trim($payload->{agent_type}) || 'subagent';
    59	    my $agent_id = _trim($payload->{agent_id});
    60	    my $transcript_path = _trim($payload->{agent_transcript_path}) || _trim($payload->{transcript_path});
    61	
    62	    my @lines = ("Subagent stop guidance for `$agent_type`:");
    63	    push @lines, "- Agent id: `$agent_id`." if length $agent_id;
    64	    push @lines, $role_context if length $role_context;
    65	    push @lines, '- The handoff must identify owned files, checks run, unresolved risks, and whether parent-side validation remains.';
    66	    push @lines, _handoff_signal_lines($payload->{last_assistant_message});
    67	
    68	    my @transcript_lines = transcript_summary_lines(
    69	        path      => $transcript_path,
    70	        max_bytes => 65_536,
    71	    );
    72	    if (@transcript_lines) {
    73	        push @lines, 'Subagent transcript signals:';
    74	        push @lines, map { "- $_" } @transcript_lines;
    75	    }
    76	
    77	    push @lines, '- If stop guardrails block, run the missing checks or document the exact environment blocker before ending the parent turn.';
    78	    return join("\n", @lines);
    79	}
